import { Key } from '@mariozechner/pi-tui';

export default function(pi) {
  pi.registerShortcut(Key.ctrlShift('z'), {
    description: 'Exercise ordinary shortcut pass-through from the editor component.',
    handler: async ctx => { ctx.ui.notify('native-ui-shortcut'); }
  });
  let count = 0;
  const widget = (_tui, theme) => ({
    render() { return [theme.fg('success', `native-ui-widget:${count}:idle`), `native-ui-theme:${theme.name}`, 'native-ui-size:120x40']; },
    invalidate() {}
  });
  pi.on('session_start', (_event, ctx) => {
    ctx.ui.setStatus('dashboard', 'native-ui:ready');
    ctx.ui.setWidget('dashboard', widget);
    ctx.ui.setWidget('dashboard-editor', (_tui, theme) => ({ render() { return [theme.fg('muted', ' native-ui-editor:pass-through')]; }, invalidate() {} }), { placement: 'belowEditor' });
    ctx.ui.setHeader(() => ({ render() { return ['native-ui:header']; }, invalidate() {} }));
    ctx.ui.setFooter((_tui, theme) => ({
      render(width) {
        const status = `dashboard: ${count === 0 ? 'native-ui:ready' : `native-ui:${count}:updated`}`;
        const cwd = process.cwd();
        const left = '0.0%/8.2k (auto)';
        const right = 'fixture-model';
        const gap = ' '.repeat(Math.max(1, 120 - left.length - right.length));
        return ['native-ui:footer', theme.fg('dim', status), theme.fg('dim', cwd), theme.fg('dim', `${left}${gap}${right}`)];
      },
      invalidate() {}
    }));
    ctx.ui.setTitle('Native UI Dashboard');
    ctx.ui.onTerminalInput(data => {
      if (data === '!') {
        count++;
        ctx.ui.setStatus('dashboard', `native-ui:${count}:updated`);
        ctx.ui.setWidget('dashboard', widget);
        return { consume: true };
      }
    });
  });
}
